    private const val MOD = 998244353
    // ROOT^(2^23)=1 & ROOT^(2^22)!=1
    private const val ROOT = 15311432
    private const val INVROOT = 469870224

    private fun bitReverse(n: Int, k: Int): Int {
        return Integer.reverse(n) ushr (32 - k)
    }

    private fun modInv(a: Int): Long {
        return modPow(a, MOD - 2)
    }

    private fun modPow(a: Int, p: Int): Long {
        if (p == 0) {
            return 1
        }
        val half = modPow(a, p / 2)
        var ans = (half * half) % MOD
        if (p % 2 == 1) {
            ans = (ans * a) % MOD
        }
        return ans
    }

    // my first fft, LETS DO THIS!!
